UPDATE t_alert_instance SET instance_status = #{target}, lifecycle_version = lifecycle_version + 1, status_reason = #{reason}, status_changed_by = #{actor}, status_changed_at = NOW(3)
, acknowledged_at = NOW(3), acknowledged_by = #{actor} , resolved_at = COALESCE(resolved_at, NOW(3)) , archived_at = NOW(3)
WHERE id = #{id} AND lifecycle_version = #{version}
